    n = 8 * qn + m8 -> 0 <= m8 <= 7 -> rs = 8 * qr -> n <= rs <= n + 7 -> 65536 < rs + rz ->
    nd = rs + rz + rz -> 4096 * (q - 1) < nd <= 4096 * q -> msz = 4096 * q + 4096 ->
    (* [comment removed for export] *)
    art_geo HI t ctx tp tsd spb ris qs -> HI <= sp - 1952 -> HI + 4096 <= sp -> sp + 2144 <= 2 ^ 47 -> sp <= stk -> stk + 16 <= sp + 4096 ->
    0 <= trp < 2 ^ 64 -> 0 <= szt < 2 ^ 64 -> sp <= trp -> trp + 8 * szt <= sp + 4096 ->
    0 <= loff -> 0x10000 <= tp + loff -> tp + loff + 4 <= 0x698000 -> 0x6638e8 <= tp - 88 -> 0x6638e8 <= tsd ->
    l2 + 2 ^ 20 <= HI -> blk + 2 ^ 23 <= HI ->
    apart l2 (2 ^ 20) t 4096 -> apart l2 (2 ^ 20) ctx 4096 -> apart l2 (2 ^ 20) 0x7fff7000 (0x10007fff8000 - 0x7fff7000) -> 0x698000 <= l2 ->
    apart blk (2 ^ 23) t 4096 -> apart blk (2 ^ 23) ctx 4096 -> apart blk (2 ^ 23) 0x7fff7000 (0x10007fff8000 - 0x7fff7000) -> 0x698000 <= blk ->
    0x698000 <= parr -> parr mod 4096 = 0 -> parr + 2 ^ 23 <= HI -> appmem parr (2 ^ 23) -> apart parr (2 ^ 23) t 4096 ->
    apart parr (2 ^ 23) ctx 4096 -> apart parr (2 ^ 23) l2 (2 ^ 20) -> apart parr (2 ^ 23) blk (2 ^ 23) ->
    0 <= nch < 16384 -> (committed = false -> nch = 0) -> 0x10000 <= nm < 2 ^ 47 ->
    (* [comment removed for export] *)
    wrA M0 (sp - 1952) 1952 -> wrA M0 t 4096 -> (committed = true -> wrA M0 parr 131072) ->
    art_alloc_rodata M0 -> art_rz_rodata M0 -> art_layout M0 -> art_tsd M0 tp key tsd ctx t -> art_prim_consts spb ris M0 ->
    cellA M0 0x1426d8 1 1 -> cellA M0 0x1c3c62 1 0 -> cellA M0 (1303448 + 3616) 8 (2 ^ 40) -> cellA M0 (1303448 + 3624) 2 16 -> cellA M0 (1303448 + 3626) 2 2048 ->
    cellA M0 0x1d34c0 8 0 -> cellA M0 (0x13f1f8 + 44) 4 4096 -> cellA M0 (0x13f1f8 + 52) 4 190 -> cellA M0 (0x13f1f8 + 85) 1 1 ->
    cellA M0 0x139e18 8 loff -> cellA M0 (tp + loff) 4 0 -> cellA M0 t 8 ctx -> cellA M0 (ctx + 8) 4 0 ->
    cellA M0 stk 8 trp -> cellA M0 (stk + 8) 8 szt ->
