        cellA M' r 8 r -> cellA M' (r + 8) 8 msz -> cellA M' (r + 16) 8 nd -> cellA M' (r + 24) 8 nch ->
        0 <= b1 < 256 -> b1 mod 4 = 1 ->
        cellA M' (ab + rz - 16) 1 2 -> cellA M' (ab + rz - 15) 1 b1 -> cellA M' (ab + rz - 14) 2 0 -> cellA M' (ab + rz - 12) 4 n ->
